mapper.select:
select sm.id, li.platform_sku_no as platformSku, li.platform_sku_name as platformSkuName, sm.product_sku_id as skuId, sm.product_sku_no as skuNo, sm.product_name as productName, li.platform_spu_no as asin, li.platform_fn_sku as fnSku, li.platform_sku_no as mSKU from listing_info li inner join sku_mapping sm on sm.listing_id = li.id and sm.is_deleted = false where ${params.sqlMap.default} and li.is_deleted = false and sm.is_expire = false
and sm.shop_id = #{params.shopId}
and li.auth_id = #{params.authId}
and li.platform = #{params.providerCode} and ( sm.has_mapping_all = true or sm.warehouse_id = #{params.warehouseId})
and sm.warehouse_id = #{params.warehouseId}

select li.id as listingId, li.platform_sku_no as platformSkuNo from listing_info li where li.is_deleted = false and li.type = #{params.type}
and li.auth_id = #{params.authId}
and li.platform_sku_no ILIKE concat('%',#{params.searchKey}::text,'%') order by case when li.platform_sku_no ILIKE concat(#{params.searchKey}::text,'%') THEN 1 when li.platform_sku_no ILIKE concat('%',#{params.searchKey}::text) THEN 2 when li.platform_sku_no ILIKE concat('%',#{params.searchKey}::text,'%') THEN 3 end , li.platform_sku_no

SELECT li.id AS listingId, sm.product_sku_id as skuId, sm.product_sku_no as skuNo, li.platform_sku_no AS platformSkuNo, li.platform_sku_name AS platformSkuName, li.platform as platform, op.owner_code as ownerCode, li.create_time as createTime FROM sku_mapping sm INNER JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE LEFT JOIN overseas_provider op on op.id = li.auth_id and op.is_deleted = false WHERE ${sqlMap.default} and sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND li.id IN
#{item}
AND li.platform IN
#{item}
